import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.CodeBuilder{URL: "ws://localhost:8080/code", ShouldOpenCodeBuilder: true}
OPEN = bytes.fromhex("1877733a2f2f6c6f63616c686f73743a383038302f636f646501")

# generated by gophertunnel b8bd735:
# &packet.CodeBuilder{URL: "", ShouldOpenCodeBuilder: false}
EMPTY = bytes.fromhex("0000")

# generated by gophertunnel b8bd735:
# &packet.CodeBuilder{URL: strings.Repeat("u", 200), ShouldOpenCodeBuilder: false}
LONG_URL = bytes.fromhex(
    "c80175757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575"
    "757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575"
    "757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575757575"
    "7575757575757575757575757575757575757575757500"
)

GOLDENS = [
    pytest.param(
        v2225.CodeBuilderPacket(url="ws://localhost:8080/code", should_open_code_builder=True),
        OPEN,
        id="open",
    ),
    pytest.param(v2225.CodeBuilderPacket(url="", should_open_code_builder=False), EMPTY, id="empty"),
    pytest.param(
        v2225.CodeBuilderPacket(url="u" * 200, should_open_code_builder=False), LONG_URL, id="200-character-url"
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_code_builder_is_packet_150(version):
    assert version.PACKETS[150] is version.CodeBuilderPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_code_builder_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_code_builder_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
